mapper.select:
SELECT 
FROM problem_review_card
WHERE id = #{cardId}
  AND user_id = #{userId}

SELECT 
FROM problem_review_card
WHERE id = #{cardId}
  AND user_id = #{userId}
FOR UPDATE

SELECT 
FROM problem_review_card
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}

SELECT prc.* FROM problem_review_card prc LEFT JOIN user_problem_note upn ON upn.user_id = prc.user_id AND upn.problem_slug = prc.problem_slug LEFT JOIN problem p ON p.slug = prc.problem_slug WHERE prc.user_id = #{userId}
AND prc.source = #{source}
AND (prc.source = 'REVIEW_FAILED' OR prc.lapses > 0)
AND ( prc.problem_slug ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(p.title_zh, '') ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(p.title_en, '') ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(upn.note_markdown, '') ILIKE CONCAT('%', #{keyword}, '%') )
ORDER BY prc.archived ASC, (prc.source = 'REVIEW_FAILED' OR prc.lapses > 0) DESC, prc.due_at ASC, prc.updated_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM problem_review_card
WHERE user_id = #{userId}
  AND archived = FALSE
  AND due_at <= #{now}

SELECT COUNT(*)
FROM problem_review_card
WHERE user_id = #{userId}
  AND archived = FALSE
  AND due_at < #{exclusiveEnd}

SELECT MIN(due_at)
FROM problem_review_card
WHERE user_id = #{userId}
  AND archived = FALSE
  AND due_at > #{after}
  AND due_at < #{exclusiveEnd}

UPDATE problem_review_card
SET archived = #{archived},
    updated_at = #{now}
WHERE id = #{cardId}
  AND user_id = #{userId}
RETURNING
